<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;

final class UserFederatedIdentityUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new UserFederatedIdentity(
            uid: 'one',
            user: new UserRef('one'),
            loginProvider: new TenantLoginProviderRef('one'),
            subject: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = UserFederatedIdentity::calculatedFields();

        // @Assert
        $this->assertEquals([ 'createdAt'], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getLoginProvider(), $other->getLoginProvider());
        $this->assertTrue($one->isLoginProviderChanged());
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new UserFederatedIdentity(
            uid: 'one',
            user: new UserRef('one'),
            loginProvider: new TenantLoginProviderRef('one'),
            subject: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );
        $other = new UserFederatedIdentity(
            uid: 'other',
            user: new UserRef('other'),
            loginProvider: new TenantLoginProviderRef('other'),
            subject: 'other',
            createdAt: (new \DateTimeImmutable('1981-09-06T14:32:45.123Z')),
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged($base));
        $this->assertEquals($one->getLoginProvider(), $other->getLoginProvider());
        $this->assertTrue($one->isLoginProviderChanged($base));
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
    }
    public function test_json_compare(): void
    {
        // @Arrange
        $one = new UserFederatedIdentity(
            uid: 'one',
            user: new UserRef('one'),
            loginProvider: new TenantLoginProviderRef('one'),
            subject: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['user']['$ref']);
        $this->assertEquals('one', $json['loginProvider']['$ref']);
        $this->assertEquals('one', $json['subject']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['createdAt']);
        $this->assertEquals(1, $json['version']);
    }
    public function test_create_store_values(): void
    {
        // @Arrange
        $one = new UserFederatedIdentity(
            uid: 'one',
            user: new UserRef('one'),
            loginProvider: new TenantLoginProviderRef('one'),
            subject: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $other = UserFederatedIdentity::create($one->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getLoginProvider(), $other->getLoginProvider());
        $this->assertTrue($one->isLoginProviderChanged());
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
        $this->assertCount(0, $one->getTheEvents());
        $this->assertCount(1, $other->getTheEvents());
    }
    public function test_update_change_values(): void
    {
        $base = new UserFederatedIdentity(
            uid: 'one',
            user: new UserRef('one'),
            loginProvider: new TenantLoginProviderRef('one'),
            subject: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );
        $other = new UserFederatedIdentity(
            uid: 'other',
            user: new UserRef('other'),
            loginProvider: new TenantLoginProviderRef('other'),
            subject: 'other',
            createdAt: (new \DateTimeImmutable('1981-09-06T14:32:45.123Z')),
            version: 2,
        );

        // @Act
        $one = $base->update($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged($base));
        $this->assertEquals($one->getLoginProvider(), $other->getLoginProvider());
        $this->assertTrue($one->isLoginProviderChanged($base));
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
        $this->assertCount(0, $other->getTheEvents());
        $this->assertCount(1, $one->getTheEvents());
    }
    public function test_delete_store_values(): void
    {
        // @Arrange
        $one = new UserFederatedIdentity(
            uid: 'one',
            user: new UserRef('one'),
            loginProvider: new TenantLoginProviderRef('one'),
            subject: 'one',
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $other = $one->delete();

        // @Assert
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getLoginProvider(), $other->getLoginProvider());
        $this->assertTrue($one->isLoginProviderChanged());
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
}
